send_js:
const ed = document.querySelector('.ql-editor[contenteditable="true"], div[contenteditable="true"]');
if (!ed) return 'ERR:no input';
ed.focus();
document.execCommand('selectAll', false);
document.execCommand('insertText', false, PROMPT);
await new Promise(r => setTimeout(r, 400));
const btn = document.querySelector('button.send-button, button[aria-label*="Send" i], button[aria-label*="Отправ" i]');
if (btn && !btn.disabled) { btn.click(); }
else {
  ed.dispatchEvent(new KeyboardEvent('keydown', {key:'Enter', code:'Enter', bubbles:true}));
  ed.dispatchEvent(new KeyboardEvent('keyup', {key:'Enter', code:'Enter', bubbles:true}));
}
return 'sent';

extract_js:
const els = document.querySelectorAll(
  'model-response .model-response-text, model-response structured-content-container, model-response .response-content, model-response');
if (!els.length) return '';
const last = els[els.length - 1];
const t = ((last.innerText || '').trim() || (last.textContent || '').trim());
return t.replace(/^Gemini said\s*/i, '').trim();
